(1222,0,0,'Die in the name of Ragnaros!',12,7,100,0,0,0,'Dark Iron Sapper'),
(1222,0,1,'The Thandol Span fell to Ragnaros.  So shall the Stonewrought Dam!',12,7,100,0,0,0,'Dark Iron Sapper'),
(1222,0,2,'King Magni Bronzebeard is a fool and a charlatan!',12,7,100,0,0,0,'Dark Iron Sapper'),
(1222,1,0,'Wahehe! I\'m taking you down with me!',12,7,100,11,0,0,'Dark Iron Sapper'),
