(1364,0,0,'This land belongs to the Dark Iron Dwarves.  Prepare to see the afterlife, $C!',12,6,100,0,0,0,'Balgaras the Foul'),
(1380,0,0,'Sorry, Huldar... But it seems I\'ve misled you.',12,7,100,0,0,0,'Saean'),
(1696,0,0,'%s goes into a frenzy!',16,0,100,0,0,0,'Targorr the Dread'),
(1716,0,0,'Why haven\'t the Stormwind guards come?',12,7,100,0,0,0,'Bazil Thredd'),
(1763,0,0,'Get those parts moving down to the ship!',12,7,100,0,0,0,'Gilnid'),
(1763,0,1,'Anyone want to take a break?  Well too bad!  Get to work you oafs!',12,7,100,0,0,0,'Gilnid'),
(1981,0,0,'We have need of your explosives. I\'ll take pleasure in killing you for them.',14,7,100,0,0,0,'Dark Iron Ambusher'),
(2091,0,0,'Your bones will break under my boot, $r!',12,1,100,0,0,0,'Chieftain Nek\'\'rosh'),
