(27439,0,0,'I know a place nearby where we can speak in private, my child. Follow me.',12,0,100,1,0,0,'High Abbot Landgren'),
(27439,1,0,'Did you think that I could not see through your flimsy disguise, $n?',12,0,100,6,0,0,'High Abbot Landgren'),
(27439,2,0,'There is much that you do not understand, $r. The Master sees all.',12,0,100,1,0,0,'High Abbot Landgren'),
