(27439,5,0,'AAAEEEEIIIiiiiiiiiiiiiiiiiiiiiiiiiiiii........................................',12,0,100,0,0,2943,'High Abbot Landgren'),
(27476,0,0,'I apologize, emissary, but the prince is away on an errand. What brings you to this desolate place?\n',12,0,100,1,3000,12719,'Valonforth 0  - Q: The Truth Shall Set Us Free'),
