(41376,0,0,'Cowards! Face the brood mother or face DIRE consequences!',14,0,100,0,0,20072,'VO_BD_Nefarian_Battle'),
(41376,1,0,'See how the shadowflame animates their bones! They fight at my command!',14,0,100,0,0,20073,'VO_BD_Nefarian_Battle'),
(41376,2,0,'Curse you, mortals! Such a callous disregard for one\'s possessions must be met with extreme force!',14,0,100,0,0,20082,'VO_BD_Nefarian_Battle'),
(41376,3,0,'I hope you can swim... in molten lava!',14,0,100,0,0,20075,'VO_BD_Nefarian_Battle'),
