(66185,0,0,'Father!',12,0,100,0,0,0,''),
(66185,1,0,'Shut up.',12,0,100,0,0,0,''),
(66185,2,0,'You raised me to be a killer.  How am I doing, daddy?',12,0,100,0,0,0,''),
