(66870,4,0,'I may have overestimated my own strength...',12,0,100,0,0,0,'Gi-Oh'),
(66870,4,1,'That\'s it, I\'ve reached my limit! This is quite the haul!',12,0,100,0,0,0,'Gi-Oh'),
